mapper.select:
SELECT

FROM inventory
WHERE location_id = #{locationId}
  AND sku_id = #{skuId}
  AND batch_no = #{batchNo}
  AND deleted = 0
FOR UPDATE

SELECT

FROM inventory
WHERE location_id = #{locationId}
  AND sku_id = #{skuId}
  AND batch_no = #{batchNo}
  AND deleted = 0

SELECT i.id, i.warehouse_id, w.name AS warehouse_name, i.location_id, l.code AS location_code, i.sku_id, p.sku_code, p.name AS sku_name, i.batch_no, i.qty, i.locked_qty, i.frozen_qty, i.available_qty, i.inbound_time, i.production_date, i.expiry_date FROM inventory i LEFT JOIN warehouse w ON w.id = i.warehouse_id AND w.deleted = 0 LEFT JOIN location l ON l.id = i.location_id AND l.deleted = 0 LEFT JOIN product p ON p.id = i.sku_id WHERE i.deleted = 0
AND (p.sku_code LIKE CONCAT('%', #{query.keyword}, '%') OR p.name LIKE CONCAT('%', #{query.keyword}, '%') OR l.code LIKE CONCAT('%', #{query.keyword}, '%'))
AND i.warehouse_id = #{query.warehouseId}
AND i.sku_id = #{query.skuId}
AND i.location_id = #{query.locationId}
AND i.batch_no = #{query.batchNo}
ORDER BY i.id DESC

SELECT i.warehouse_id AS group_id, w.code AS group_code, w.name AS group_name, SUM(i.qty) AS qty, SUM(i.locked_qty) AS locked_qty, SUM(i.frozen_qty) AS frozen_qty, SUM(i.available_qty) AS available_qty, COUNT(DISTINCT i.sku_id) AS sku_count, COUNT(DISTINCT i.location_id) AS location_count FROM inventory i LEFT JOIN warehouse w ON w.id = i.warehouse_id AND w.deleted = 0 WHERE i.deleted = 0 AND i.qty > 0
AND i.warehouse_id = #{warehouseId}
GROUP BY i.warehouse_id, w.code, w.name ORDER BY qty DESC

SELECT l.zone_id AS group_id, z.code AS group_code, z.name AS group_name, z.zone_type AS group_type, w.name AS parent_name, SUM(i.qty) AS qty, SUM(i.locked_qty) AS locked_qty, SUM(i.frozen_qty) AS frozen_qty, SUM(i.available_qty) AS available_qty, COUNT(DISTINCT i.sku_id) AS sku_count, COUNT(DISTINCT i.location_id) AS location_count FROM inventory i JOIN location l ON l.id = i.location_id LEFT JOIN zone z ON z.id = l.zone_id LEFT JOIN warehouse w ON w.id = i.warehouse_id AND w.deleted = 0 WHERE i.deleted = 0 AND i.qty > 0
AND i.warehouse_id = #{warehouseId}
GROUP BY l.zone_id, z.code, z.name, z.zone_type, w.name ORDER BY qty DESC

SELECT i.sku_id AS group_id, p.sku_code AS group_code, p.name AS group_name, SUM(i.qty) AS qty, SUM(i.locked_qty) AS locked_qty, SUM(i.frozen_qty) AS frozen_qty, SUM(i.available_qty) AS available_qty, COUNT(DISTINCT i.sku_id) AS sku_count, COUNT(DISTINCT i.location_id) AS location_count FROM inventory i LEFT JOIN product p ON p.id = i.sku_id WHERE i.deleted = 0 AND i.qty > 0
AND i.warehouse_id = #{warehouseId}
GROUP BY i.sku_id, p.sku_code, p.name ORDER BY qty DESC

SELECT i.id AS inventory_id, i.warehouse_id AS warehouse_id, w.name AS warehouse_name, l.code AS location_code, p.sku_code AS sku_code, p.name AS sku_name, i.batch_no AS batch_no, i.qty AS qty, i.production_date AS production_date, i.expiry_date AS expiry_date, DATEDIFF(i.expiry_date, CURDATE()) AS days_to_expire FROM inventory i LEFT JOIN warehouse w ON w.id = i.warehouse_id AND w.deleted = 0 LEFT JOIN location l ON l.id = i.location_id LEFT JOIN product p ON p.id = i.sku_id WHERE i.deleted = 0 AND i.qty > 0 AND i.expiry_date IS NOT NULL AND i.expiry_date <= DATE_ADD(CURDATE(), INTERVAL #{expireDays} DAY)
AND i.warehouse_id = #{warehouseId}
ORDER BY i.expiry_date ASC, i.id ASC LIMIT 200

SELECT i.id AS inventory_id, i.warehouse_id AS warehouse_id, w.name AS warehouse_name, l.code AS location_code, p.sku_code AS sku_code, p.name AS sku_name, i.batch_no AS batch_no, i.qty AS qty, i.frozen_qty AS frozen_qty, i.available_qty AS available_qty FROM inventory i LEFT JOIN warehouse w ON w.id = i.warehouse_id AND w.deleted = 0 LEFT JOIN location l ON l.id = i.location_id LEFT JOIN product p ON p.id = i.sku_id WHERE i.deleted = 0 AND i.frozen_qty > 0
AND i.warehouse_id = #{warehouseId}
ORDER BY i.frozen_qty DESC, i.id ASC LIMIT 200

SELECT l.id AS location_id, l.warehouse_id AS warehouse_id, w.name AS warehouse_name, z.name AS zone_name, l.code AS location_code, l.name AS location_name, l.capacity AS capacity, l.used_capacity AS used_capacity, (l.used_capacity - l.capacity) AS over_qty FROM location l LEFT JOIN warehouse w ON w.id = l.warehouse_id AND w.deleted = 0 LEFT JOIN zone z ON z.id = l.zone_id WHERE l.deleted = 0 AND l.capacity > 0 AND l.used_capacity > l.capacity
AND l.warehouse_id = #{warehouseId}
ORDER BY over_qty DESC LIMIT 200
